import { MakeLogicType, actions, kea, path, reducers } from 'kea'

import type { ComparisonMode } from 'lib/components/VisualImageDiffViewer/VisualImageDiffViewer'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface visualReviewPreferencesLogicValues {
    addImagesToComment: boolean
    comparisonMode: ComparisonMode
    lastRepoByTeam: Record<string, string>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface visualReviewPreferencesLogicActions {
    rememberRepo: (
        teamId: number,
        repoFullName: string
    ) => {
        repoFullName: string
        teamId: number
    }
    setAddImagesToComment: (enabled: boolean) => {
        enabled: boolean
    }
    setComparisonMode: (mode: ComparisonMode) => {
        mode: ComparisonMode
    }
}

export type visualReviewPreferencesLogicType = MakeLogicType<
    visualReviewPreferencesLogicValues,
    visualReviewPreferencesLogicActions
>

export const visualReviewPreferencesLogic = kea<visualReviewPreferencesLogicType>([
    path(['products', 'visual_review', 'frontend', 'scenes', 'visualReviewPreferencesLogic']),
    actions({
        setComparisonMode: (mode: ComparisonMode) => ({ mode }),
        setAddImagesToComment: (enabled: boolean) => ({ enabled }),
        rememberRepo: (teamId: number, repoFullName: string) => ({ teamId, repoFullName }),
    }),
    reducers({
        comparisonMode: [
            'sideBySide' as ComparisonMode,
            { persist: true, prefix: 'visual_review_' },
            {
                setComparisonMode: (_, { mode }) => mode,
            },
        ],
        addImagesToComment: [
            false,
            { persist: true, prefix: 'visual_review_' },
            {
                setAddImagesToComment: (_, { enabled }) => enabled,
            },
        ],
        // The `/visual-review` entry point opens the repo a team used last.
        lastRepoByTeam: [
            {} as Record<string, string>,
            { persist: true, prefix: 'visual_review_' },
            {
                rememberRepo: (state, { teamId, repoFullName }) => ({ ...state, [teamId]: repoFullName }),
            },
        ],
    }),
])
